{s:QZ,k:'pq',term:'Question 1',lv:'U',n:1,q:"Why does the specific gravity of the electrolyte fall during discharge?",say:'Question one. Why does the specific gravity of the acid fall during discharge?',cues:{k:'Question one',q:'Why does the'},pause:3.4},
{s:QZ,k:'pa',term:'Answer 1',lv:'U',n:1,q:"Why does the specific gravity of the electrolyte fall during discharge?",say:'The discharge reaction uses up sulfuric acid. It also makes water. So the liquid becomes less dense, and the specific gravity drops from about one point two eight towards one point one two.',cues:{a1:'The discharge reaction',a2:'It also makes',a3:'So the liquid'},al:[["The discharge reaction uses up sulfuric acid.",'a1'],["It also produces water.",'a2'],["The liquid gets less dense: SG falls from about 1.26–1.28 towards about 1.12.",'a3']],vis:(c,u,b)=>{
 /* two cells drawn as beakers; orange dots acid, blue dots water (a picture, not a count) */
 const beaker=(x,acid,water,lab,sg,col)=>{let s=`<path d="M${x},70 L${x},360 Q${x},380 ${x+20},380 L${x+220},380 Q${x+240},380 ${x+240},360 L${x+240},70" fill="none" stroke="${AE_DARK}" stroke-width="4"/><rect x="${x+4}" y="120" width="232" height="256" fill="${AE_ACID}" fill-opacity=".6"/>`;
  let k=0;for(let r=0;r<5;r++)for(let q=0;q<4;q++){const cx=x+40+q*54,cy=150+r*48;s+=`<circle cx="${cx}" cy="${cy}" r="14" fill="${k<acid?ORG:BLU}"/>`;k++}
  return s+AE_T(x+120,420,lab,{fs:24,fw:800,a:'middle',fill:col})+AE_T(x+120,456,sg,{fs:22,fw:700,a:'middle',fill:AE_GREY})};
 return AE_T(20,40,'● acid',{fs:22,fw:800,fill:ORG})+AE_T(140,40,'● water',{fs:22,fw:800,fill:BLU})+beaker(20,16,4,'charged','SG about 1.28',ORG)+
  g('pop',tk(c,'a1'),beaker(350,4,16,'discharged','SG about 1.12',BLU))+
  g('pop',tk(c,'a2'),AE_arrow(268,250,338,250,AE_DARK,4,16))+
  g('pop',tk(c,'a3'),`<rect x="300" y="18" width="300" height="40" rx="8" fill="${GRN}"/>`+AE_T(450,46,'less dense: SG falls',{fs:22,fw:800,a:'middle',fill:'#FFFFFF'}))}},
{s:QZ,k:'pq',term:'Question 2',lv:'A',n:2,q:"A 0.47 µF suppression capacitor sits at the alternator B+ terminal. Find its reactance at 100 Hz (ripple region) and at 1 MHz.",say:'Question two. A zero point four seven microfarad capacitor sits at the alternator output. Find its reactance at one hundred hertz and one megahertz.',cues:{k:'Question two',q:'A zero point'},pause:3.4},
{s:QZ,k:'pa',term:'Answer 2',lv:'A',n:2,q:"A 0.47 µF suppression capacitor sits at the alternator B+ terminal. Find its reactance at 100 Hz (ripple region) and at 1 MHz.",say:'Use one over two pi f C. At one hundred hertz: about three thousand three hundred eighty-six ohms. At one megahertz: zero point three three nine. So it shorts radio noise, but barely loads the supply.',pause:1,cues:{fk:'Use one over',k1:'At one hundred',k1b:'about three thousand',k2:'At one megahertz',k2b:'zero point three',k3:'So it shorts'},calc:{f:['XC = 1 ÷ (2πfC)'],hint:'C = 0.47 µF = 0.47 × 10⁻⁶ F.',fk:'fk',steps:[["At 100 Hz",["1 ÷ (2π × 100 × 0.47 × 10⁻⁶)","XC = 3386 Ω"],["k1","k1b"]],["At 1 MHz",["1 ÷ (2π × 10⁶ × 0.47 × 10⁻⁶)","XC = 0.339 Ω"],["k2","k2b"]],["Meaning","shorts RF noise, barely loads the supply","k3"]],live:[0,1,2]}},
{s:QZ,k:'pq',term:'Question 3',lv:'N',n:3,q:"A battery reads 12.6 V on open circuit but fails a load test. Explain.",say:'Question three. A battery reads twelve point six volts at rest, but fails a load test. Explain why.',cues:{k:'Question three',q:'A battery reads'},pause:3.4},
{s:QZ,k:'pa',term:'Answer 3',lv:'N',n:3,q:"A battery reads 12.6 V on open circuit but fails a load test. Explain.",say:'At rest, almost no current flows. So a surface charge, or a high-resistance cell, can still show a good voltage. The load test draws a big current, and exposes weak plates or poor connections.',cues:{a1:'At rest, almost',a2:'So a surface',a3:'The load test'},al:[["At rest almost no current flows.",'a1'],["Surface charge or a high-resistance cell can still give a good rest voltage.",'a2'],["The load test draws current and exposes weak plates or poor connections.",'a3']],vis:(c,u,b)=>{
 /* bars from the worked example: both 12.6 V at rest; at 225 A, A 10.1 V and B 9.2 V against the 9.6 V limit */
 const y0=430,sc=70,bar=(x,v,col,lab)=>`<rect x="${x}" y="${AE_vy(v,y0,sc)}" width="90" height="${(v-8)*sc}" rx="4" fill="${col}" fill-opacity=".35" stroke="${col}" stroke-width="3"/>`+AE_T(x+45,AE_vy(v,y0,sc)+(v<9.6?30:-10),v.toFixed(1)+' V',{fs:22,fw:800,a:'middle',fill:col});
 return AE_T(20,34,'worked example: batteries A and B',{fs:22,fw:700,fill:AE_GREY})+AE_L(20,y0,600,y0,AE_DARK,3)+
  g('pop',tk(c,'a1'),bar(40,12.6,AE_GREY,'')+bar(150,12.6,AE_GREY,'')+AE_T(145,y0+34,'at rest',{fs:22,fw:800,a:'middle',fill:AE_DARK}))+
  g('pop',tk(c,'a2'),AE_T(145,66,'both look healthy',{fs:22,fw:800,a:'middle',fill:AE_GREY})+AE_T(95,y0+62,'A',{fs:22,fw:800,a:'middle',fill:AE_DARK})+AE_T(205,y0+62,'B',{fs:22,fw:800,a:'middle',fill:AE_DARK}))+
  g('pop',tk(c,'a3'),bar(330,10.1,GRN,'')+bar(440,9.2,RED,'')+AE_T(435,y0+34,'at 225 A',{fs:22,fw:800,a:'middle',fill:AE_DARK})+AE_T(385,y0+62,'A',{fs:22,fw:800,a:'middle',fill:AE_DARK})+AE_T(495,y0+62,'B',{fs:22,fw:800,a:'middle',fill:AE_DARK})+
   AE_L(310,AE_vy(9.6,y0,sc),600,AE_vy(9.6,y0,sc),RED,3,'stroke-dasharray="8 6"')+AE_T(600,AE_vy(9.6,y0,sc)-56,'limit 9.6 V',{fs:22,fw:800,a:'end',fill:RED}))}},
{s:LS,k:'figs',term:'Your notes',title:'For your notes',say:'Your free notes are the PDF in the description. Redraw the source, path and sink chart, one cell, and the reserve-capacity curves.',cues:{t:'Your free notes',f:'Redraw the source'},tags:[["Free notes for this lesson (PDF)", "link in the description"], ["The three chapters", "Electromagnetic compatibility and interference suppression; battery design, lead-acid construction and working; battery ratings, testing and maintenance-free batteries"], ["Key terms and glossary", "at the end of the notes"]],figs:[["Source, coupling path and sink", "Every EMC problem is a source, a coupling path and a sink; suppression is applied at all three."], ["One lead-acid cell", "PbO₂ positive and spongy Pb negative plates alternate with porous separators in dilute H₂SO₄; six cells give 12.6 V at rest."], ["The reserve-capacity test at 25 A", "A battery that meets its 100 min rating reaches 10.5 V at 100 min; battery B gets there after 72 min, having delivered only 30 Ah."]],note:"Sources your free notes draw on: Robert Bosch GmbH (ed.), Automotive Electrics and Automotive Electronics; Tom Denton, Automobile Electrical and Electronic Systems; P. L. Kohli, Automotive Electrical Equipment"},
{s:OUT,k:'outro',term:'Outro',say:'So remember: fix noise at its source, know your plates, and read the ratings. Next time, the charging system and charging circuit. See you there!',cues:{f:'So remember',w1:'fix noise at',w2:'know your plates',w3:'and read the',n:'Next time',s:'See you there'},words:[['FIX THE SOURCE FIRST','BLU','w1'],['PbO₂ IS POSITIVE','ORG','w2'],['RATINGS, THEN TESTS','GRN','w3']],next:["NEXT TIME", "Next lesson", "Charging system and charging circuit", "book"],end:'See you there!'}
