function EXTRA(R,ICON){
 /* hook: the relay coil spike, and the box of six cells */
 ICON.aeSpike=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${AE_box(0,0,380,170,{fill:'#FFFFFF',st:RED,sw:3,r:18})}
  ${AE_coil(56,24,3,15)}${AE_T(30,150,'coil off',{fs:22,fw:800,fill:AE_DARK})}
  ${AE_poly([[130,130],[200,130],[212,26],[224,130],[350,130]],RED,5)}${AE_T(232,62,'≈ 14,000 V',{fs:26,fw:800,fill:RED})}</g>`;
 ICON.aeBox=(x,y)=>{let s=AE_box(0,0,380,170,{fill:'#FFFFFF',st:BLU,sw:3,r:18})+AE_box(24,44,332,92,{r:8,st:AE_DARK,sw:4,fill:'#F1F3F5'});
  for(let i=0;i<6;i++)s+=AE_box(36+i*54,56,44,68,{r:4,st:BLU,sw:3,fill:'#E7F5FF'})+AE_T(58+i*54,98,'2.1',{fs:22,fw:800,a:'middle',fill:BLU});
  s+=`<rect x="60" y="28" width="30" height="16" rx="3" fill="${RED}"/><rect x="290" y="28" width="30" height="16" rx="3" fill="${AE_DARK}"/>`+AE_T(190,162,'six cells: 12.6 V',{fs:24,fw:800,a:'middle',fill:BLU});
  return `<g transform="translate(${x-190} ${y-85})">${s}</g>`};
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.aeEmc=(x,y)=>{let s='';
  [['source',ORG,0],['path',PUR,150],['sink',GRN,300]].forEach(([n,col,x0])=>{s+=AE_box(x0,90,110,80,{r:10,st:col,sw:4})+AE_T(x0+55,140,n,{fs:24,fw:800,a:'middle',fill:col})});
  s+=AE_arrow(112,130,146,130,AE_DARK,3,12)+AE_arrow(262,130,296,130,AE_DARK,3,12)+AE_poly([[20,60],[40,60],[50,10],[60,60],[90,60]],ORG,4)+
   AE_T(55,220,'fix here',{fs:24,fw:800,a:'middle',fill:ORG})+AE_T(55,250,'first',{fs:24,fw:800,a:'middle',fill:ORG})+AE_wave(320,50,70,8,2,GRN,3);
  return `<g transform="translate(${x-205} ${y-140})">${s}</g>`};
 ICON.aeCell=(x,y)=>{let s=`<rect x="20" y="40" width="370" height="230" rx="10" fill="${AE_ACID}" stroke="${AE_DARK}" stroke-width="4"/>`;
  for(let i=0;i<5;i++)s+=AE_plate(48+i*70,64,34,180,i%2?'neg':'pos');
  s+=AE_T(65,30,'+ PbO₂',{fs:22,fw:800,a:'middle',fill:AE_BROWN})+AE_T(135,30,'− Pb',{fs:22,fw:800,a:'middle',fill:AE_DARK})+AE_T(205,300,'in dilute H₂SO₄',{fs:24,fw:800,a:'middle',fill:ORG});
  return `<g transform="translate(${x-205} ${y-160})">${s}</g>`};
 ICON.aeLoad=(x,y)=>{const y0=290,sc=55;let s=AE_L(0,y0,410,y0,AE_DARK,3);
  [[30,12.6,AE_GREY,'rest'],[160,10.1,GRN,'A'],[290,9.2,RED,'B']].forEach(([x0,v,col,n])=>{s+=`<rect x="${x0}" y="${AE_vy(v,y0,sc)}" width="90" height="${(v-8)*sc}" rx="4" fill="${col}" fill-opacity=".35" stroke="${col}" stroke-width="3"/>`+AE_T(x0+45,AE_vy(v,y0,sc)+(v<9.6?30:-10),v.toFixed(1),{fs:24,fw:800,a:'middle',fill:col})+AE_T(x0+45,y0+30,n,{fs:22,fw:800,a:'middle',fill:AE_DARK})});
  s+=AE_L(140,AE_vy(9.6,y0,sc),410,AE_vy(9.6,y0,sc),RED,3,'stroke-dasharray="8 6"');
  return `<g transform="translate(${x-205} ${y-150})">${s}</g>`};
}
